head.b:skin:
/*-----------------------------------------------
Blogger Template Style
Name: Movie Premium
Version:   2.0
Themes by: Phantom / Y!H: phantombabby
----------------------------------------------- */
#navbar-iframe,#blog-pager,.get_breadcrumb,#anc_pl center{display:none;}
.filter_min .get_breadcrumb{display:block;}
body{background:#0C1323 url(http://3.bp.blogspot.com/-by4fmWpeOkk/U48FtqlVnWI/AAAAAAAAQqI/FwT11qstQcc/s1600/background.jpg) repeat;font-size:11px;font-family:Tahoma,Geneva,sans-serif;color:#2a2a2a;margin:0;padding:0}
a{color:#2a2a2a;text-decoration:none;outline:none}
*{margin:0;padding:0}
input{border:none;background:none}
ul,li{list-style:none}
h1{font-size:18px;font-weight:bold}
h2{font-size:16px;font-weight:bold}
h3{font-size:14px;font-weight:bold}
h4{font-size:13px;font-weight:bold}
h5{font-size:12px;font-weight:bold}
.mt5{margin-top:5px !important}
.mt10{margin-top:10px !important}
.mt20{margin-top:20px !important}
.mb5{margin-bottom:5px}
.time{color:#9c9c9c;font-size:11px;font-weight:normal;display:inline-block}
.thumbnail{box-shadow:0 0 5px #ccc}
.pagination{margin:0 20px 10px;font-family:Arial,Helvetica,sans-serif;display:block;overflow:hidden}
.pagination .pagi_ul a{background:#ddd;float:left;width:24px;height:24px;text-align:center;margin-right:7px;line-height:24px;border-radius:3px}
.pagination .pagi_ul a:hover{background:#1E4FC1 !important;color:#fff}
.pagination .pagi_ul .current{background:#112c6d !important;color:#fff;font-weight:bold}
.pagination .pagi_ul .page_label{margin-right:10px;font-weight:bold;text-transform:uppercase;height:24px;line-height:24px}
.pagination .pagi_ul li{float:left}
.fll{float:left}
.ovf{overflow:hidden !important}
.flr{float:right}
.clr{clear:both}
.content{padding:5px}
.pattern{background:url(http://1.bp.blogspot.com/-tY8A_nkN9aE/U48J8fpr2nI/AAAAAAAAQtE/1qktPMcpTZw/s1600/pattern.jpg) repeat !important;border-top:1px solid #eee;border-bottom:1px solid #eee}
.sprites{background-image:url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png)}
.icons16{width:16px;height:16px;display:inline-block;margin-right:5px;vertical-align:text-bottom;*display:none}
.icon_blog{background-position:-1px -1px}
.icon_chart{background-position:-2px -22px}
.icon_hot{background-position:-2px -41px}
.icon_tag{background-position:-20px -1px}
.icon_like{background-position:-160px -0}
.btn_like{background-position:-230px 2px}
.btn_closeads{background-position:-230px -16px}
.btn_auto{background-position:-229px -35px}
.btn_zoom{background-position:-230px -58px}
.btn_zoomin{background-position:-250px -58px}
.btn_offlight{background-position:-230px -80px}
.btn_onlight{background-position:-250px -80px}
.f_views_icon{background-position:-230px -100px}
/* Wrapper */#wrapper{background:url(http://1.bp.blogspot.com/-mdFHKAaPzgY/U48F1KnaeoI/AAAAAAAAQsU/OKfQk9Vl9mY/s1600/wrapper.jpg) top center no-repeat;overflow:auto}
/* Header */.header{width:100%;background:#000 url(http://4.bp.blogspot.com/-ETQvPrICdVQ/U48FwN4DTAI/AAAAAAAAQqw/Ebn8oOuyXns/s1600/header_bg.png) repeat;margin:0 auto;height:114px}
.header .content{width:980px;margin:0 auto;padding:0;position:relative;z-index:10}
.header .logo_shadow{position:absolute;left:-54px;top:0;z-index:1;background:url(http://1.bp.blogspot.com/-9eMTnz6msU8/U48Fx3RdmhI/AAAAAAAAQrY/4wLN25DlPW8/s1600/logo_shadow.png) 0 0 no-repeat;width:294px;height:122px}
.header .logo{width:175px;height:72px;background:url(https://lh3.googleusercontent.com/-_xlDLMEqvpo/U24Dn5IuOEI/AAAAAAAAASw/LFOPZjjyTBQ/w170-h44-no/fanphim.png) 0 0 no-repeat;position:absolute;top:5px;left:10px;z-index:2}
.header .logo a{color:#ddd;display:block;font-size:10px;font-weight:bold;letter-spacing:2px;padding-left:57px;width:100%;overflow:hidden;padding-top:37px}
.header .search{z-index:30;border-radius:5px;width:400px;height:37px;display:inline-block;position:absolute;top:18px;left:210px;background:#fff url(http://3.bp.blogspot.com/-3CA7L0Qw-lg/U48FzlyGzWI/AAAAAAAAQr0/boCeE1C4KKY/s1600/search_bg.png) top repeat-x;position:relative}
.header .search .search_input{display:inline-block;width:350px;margin:5px 8px;height:27px;line-height:27px;font-family:Arial,Helvetica,sans-serif;font-size:12px}
.header .search .search_submit{position:absolute;top:0;right:-5px;background-position:0 -120px;width:40px;height:37px;text-indent:-999em;cursor:pointer}
.header .search .search_submit:hover{background-position:0 -157px;}
.search-item{display:none;position:fixed;left:0;top:0;width:100%;height:100%;z-index:22;}
.search-item .boiden{background:black;width:200%;height:100%;opacity:0.8;cursor:pointer;}
.search-item .block_new{width:988px;z-index:33;background:#fff;overflow:hidden;position:absolute;top:0;left:50%;height:100%;visibility:visible;padding-right:15px;overflow-y:scroll;opacity:1;margin:0 auto 0 -494px;}
.search-item .tabs{height:1030px;background:#fff;width:988px;overflow:hidden;opacity:1;}
.search-item .tabs_content{background:#fff;width:100%!important;opacity:1;border:none!important;margin:0;}
.search-item .close{position:absolute;top:0;left:460px;background:url(http://pubvn.tv/phim/images/imgv10/pub_icon.png) -139px -99px no-repeat;height:27px;width:68px;cursor:pointer;font-size:0;}
.search-item h1{text-align:center;margin-top:50px;}
.header .header_right{position:absolute;left:650px;top:18px;}
.header .header_right .yeuthich{background-position:-42px 0;margin-right:20px;width:43px;height:39px;display:inline-block}
.header .header_right .yeucau{background-position:-94px 1px;width:62px;height:39px;display:inline-block}
.header .header_blog{position:absolute;right:0;top:0;width:120px;padding:18px 25px;height:54px;background:#132C6F;display:inline-block;color:#fff}
.header .header_blog span{font-size:14px;font-weight:bold;font-family:Arial,Helvetica,sans-serif}
/* Menu */.menu{width:980px;height:38px;border-bottom:2px #80b500 solid;position:absolute;top:72px;left:0;background:url(http://3.bp.blogspot.com/-QLeIi0RaY9I/U48FyofToJI/AAAAAAAAQrk/4a9KPtLDy3Q/s1600/menu_bg.png) repeat;border-top:1px solid #272f4b;z-index:10}
.menu #menu_ul{position:relative;z-index:50}
.menu .menu_home{height:38px}
.menu #menu_ul .menu_li_home{height:38px;display:inline-block;background:url(http://2.bp.blogspot.com/-44IsUJQNYPw/U48FwusNfwI/AAAAAAAAQq4/_SFe2WewRB0/s1600/icon_home.png) center center no-repeat}
.menu #menu_ul li{float:left;background:url(http://1.bp.blogspot.com/-d6-d56g1P-0/U48Fy7_0roI/AAAAAAAAQrg/tkB2CORM4Cw/s1600/menu_li.png) right repeat-y;position:relative;z-index:50}
.menu a{color:#fff;text-transform:uppercase;font-weight:bold;font-family:Arial;font-size:12px;height:38px;line-height:38px;display:inline-block;padding-left:20px;padding-right:20px;position:relative}
.menu #menu_ul li:hover,.menu #menu_ul .active{-moz-box-shadow:inset 0 0 10px 10px rgba(6,13,21,0.7);-webkit-box-shadow:inset 0 0 10px 10px rgba(6,13,21,0.7);box-shadow:inset 0 0 10px 10px rgba(6,13,21,0.7)}
.menu .login_menu{float:right;width:205px;margin-top:6px}
.menu .login_menu .l_m_login{-moz-box-shadow:inset 0 0 10px 10px rgba(6,13,21,0.7);-webkit-box-shadow:inset 0 0 10px 10px rgba(6,13,21,0.7);box-shadow:inset 0 0 10px 10px rgba(6,13,21,0.7)}
/* menu expand */.top_menu_expand{position:absolute;top:38px;left:-2px;z-index:5;color:#fff;display:none}
.top_menu_expand a{color:#fff}
.top_menu_expand .t_m_table{color:#fff;background:#555;border:2px solid #80B500;padding-bottom:0;overflow:hidden;width:453px;position:relative;z-index:50}
.top_menu_expand .t_m_table a{font-family:arial,tahoma !important;text-transform:none;padding:0 10px !important;margin:0 !important;display:block !important;float:left;margin-top:-1px !important;margin-left:-1px !important;height:30px;line-height:30px;width:130px !important;border:1px solid #333 !important;font-weight:normal !important;font-size:11px !important}
.top_menu_expand .t_m_table a:hover{background:#333 !important}
.top_menu_expand .t_m_table ul{clear:both}
.top_menu_expand .t_m_table ul li{float:left;position:relative;background:none !important}
.top_menu_expand .t_m_table ul li:hover{background:#333 !important;border:none !important;margin-top:0 !important;margin-left:0 !important}
.top_menu_expand .t_m_table1{color:#fff;background:#555;border:2px solid #80B500;padding-bottom:0;overflow:hidden;width:151px;position:relative;z-index:50}
.top_menu_expand .t_m_table1 a{font-family:arial,tahoma !important;text-transform:none;padding:0 10px !important;margin:0 !important;display:block !important;float:left;margin-top:-1px !important;margin-left:-1px !important;height:30px;line-height:30px;width:130px !important;border:1px solid #333 !important;font-weight:normal !important;font-size:11px !important}
.top_menu_expand .t_m_table1 a:hover{background:#333 !important}
.top_menu_expand .t_m_table1 ul{clear:both}
.top_menu_expand .t_m_table1 ul li{float:left;position:relative;background:none !important}
.top_menu_expand .t_m_table1 ul li:hover{background:#333 !important;border:none !important;margin-top:0 !important;margin-left:0 !important}
/* Ads */.ads_full{width:100%;margin-bottom:5px}
.ads_full img{width:970px}
.ads_sidebar{margin-bottom:5px;width:300px}
.ads_sidebar img{width:300px}
/* main */.main{width:980px;position:relative;background:#f8f8f8 url(http://2.bp.blogspot.com/-uwJ_WSQC7SU/U48FyGuA8FI/AAAAAAAAQrQ/J0onQIDwyAk/s1600/main_bg.png);overflow:hidden;margin:0 auto}
.main .content{overflow:hidden}
.main .c_m{width:665px;float:left;position:relative;margin-right:5px;min-height:300px;overflow:hidden}
.main .sidebar{width:300px;float:right;overflow:hidden}
/* slide */.slide{margin:0 auto;height:272px;width:980px;overflow:hidden;position:relative;z-index:2}
.slide ul li{float:left;width:196px;height:272px;position:relative}
.slide ul li .sl_thumb{width:196px;height:272px}
.slide ul li .slide_shadow{width:48px;height:272px;background:url(http://1.bp.blogspot.com/-e93lU-F2IX4/U48IqmEXbAI/AAAAAAAAQso/7E-ZCz4BiDU/s1600/slide_shadow.png) right repeat-y;top:0;right:0;position:absolute}
.slide ul li .slide_desc{position:absolute;bottom:0;left:0}
.slide ul li .slide_desc .sld_content{min-height:32px;width:196px;position:relative;background:url(http://1.bp.blogspot.com/-KZ5xBupEd6M/U48J9PPk6II/AAAAAAAAQtM/nvgXXQUxgl0/s1600/dot.png) repeat;display:inline-block;text-align:center;padding-top:6px;padding-bottom:6px}
.slide ul li .slide_desc h1{font-size:11px;color:#fff;line-height:1.4em}
.slide ul li .slide_desc h2{font-weight:normal;font-size:11px;color:#fff;line-height:1.4em}
.slide ul li .slide_desc .name_sl1{font-size:11px;color:#fff;line-height:1.4em;font-weight:bold}
.slide ul li .slide_desc .name_sl2{font-weight:normal;font-size:11px;color:#fff;line-height:1.4em}
.slide ul li .slide_desc .sl_tag_target{position:relative}
.slide ul li .sl_tag{background:#ff0;height:16px;padding-left:8px;padding-right:8px;font-weight:bold;text-transform:uppercase;line-height:16px;border-radius:16px;display:inline-block;font-family:Arial;font-size:11px;position:absolute;left:5px;top:5px}
/* block hot */.block_hot{width:100%;clear:both;overflow:hidden}
.block_hot .b_h_main{width:300px;float:left;margin-bottom:10px;overflow:hidden}
.block_hot .b_h_main .tabs .tabs_content{width:298px;height:295px;border-top:none;background:#fff}
.block_hot .b_h_main .tabs .tabs_content ul li{height:28px;line-height:28px;border-bottom:1px dashed #ccc;margin:0 5px;position:relative}
.block_hot .b_h_main .tabs .tabs_content ul li .chapter{position:absolute;top:0;right:0}
.block_hot .b_h_main .tabs .tabs_content ul li h1{font-weight:normal;font-size:11px}
.block_hot .b_h_main .tabs .nav a{width:119px;*width:118px !important}
.block_hot .b_h_main .tabs .tabs_container{margin-right:-1px}
/* Block new */.block_new{width:100%;clear:both;position:relative}
.block_new .tabs .tabs_content{width:663px;background:#fff;padding-bottom:10px;margin-bottom:10px;margin-top:0}
.block_new .tabs .tabs_content .l_w_l{overflow:hidden;padding:10px}
.block_new .tabs .tabs_content .l_w_l li{float:left;width:160px;text-align:center;height:236px;overflow:hidden;margin-top:10px;position:relative}
.block_new .tabs .tabs_content .l_w_l li .thumbnail{background:#FFF url(http://4.bp.blogspot.com/-0j9WHHMXhWs/U48FxDad3oI/AAAAAAAAQrI/JX_aYcHNbyc/s1600/loading.gif) no-repeat center center;width:140px;height:186px}
.block_new .tabs .tabs_content .l_w_l li .f_desc{font-weight:bold}
.block_new .tabs .tabs_content .l_w_l li .f_desc h1{font-size:11px}
.block_new .tabs .tabs_content .l_w_l li .f_desc h2{font-weight:normal;font-size:11px}
.block_new .tabs .tabs_content .l_w_l li .f_tag{font-family:Arial,Helvetica,sans-serif;font-size:10px;text-transform:uppercase;position:absolute;top:168px;left:13px;padding-left:8px;padding-right:8px;font-size:11px;font-weight:bold;background:#FF0;height:14px;border-radius:14px;display:inline-block;line-height:14px}
.block_new .tabs .tabs_content .l_w_l li .year{right:9px !important;left:auto !important;color:#fff !important}
.block_new .tabs .tabs_content .l_w_l li .year .f_t_f{background:url(#) 0 -36px no-repeat}
.block_new .tabs .tabs_content .l_w_l li .year .f_t_c{background:url(#) 0 -18px repeat-x;text-align:right !important}
.block_new .tabs .tabs_content .l_w_l li .year .f_t_e{background:url(#) 0 0 no-repeat}
.block_new .tabs .tabs_container ul li a{padding-left:25px;padding-right:25px;margin-bottom:-1px;position:relative}
/* tabs */.tabs{}
.tabs .tabs_container{}
.tabs .tabs_container ul li{float:left}
.tabs .tabs_container ul li a{padding-left:15px;padding-right:15px;height:34px;border:1px solid #fff;line-height:34px;text-align:center;background:#171f35;color:#fff;display:inline-block;font-weight:bold;font-size:12px;margin-left:-1px}
.tabs .tabs_container ul li .active{background:#498600;border:1px solid #fff;text-align:center;z-index:9 !important;color:#fff}
.tabs .tabs_content{clear:both;border:1px solid #c1c1c1;display:inline-block;margin-top:-1px}
.chart{width:100%;position:relative;overflow:hidden}
.bar_title{background:#030714;position:relative;height:37px;width:100%;color:#fff}
.bar_title span{font-size:14px;font-family:Arial,Helvetica,sans-serif;text-transform:uppercase;font-weight:bold;line-height:35px;padding-left:10px}
.bar_title a {color:#fff}
.bar_title span .sprites{margin-right:10px !important}
.chart .tabs .tabs_container ul{margin-right:-1px}
.chart .tabs .tabs_container ul li a{height:34px;border:1px solid #fff;line-height:34px;text-align:center;display:inline-block;font-weight:bold;font-size:12px;text-align:center;width:98px;*width:98px !important;padding:0 !important}
.chart .tabs .tabs_container ul li .active{border:1px solid #fff;text-align:center}
.chart .tabs .tabs_content{width:298px;margin-left:0 !important;margin-bottom:5px;background:#fff;border-top:none}
.chart .top_chart{padding:5px !important}
.chart .top_chart .t_c_numb{background-position:0 -86px;width:34px;height:26px;text-align:center;padding-top:4px;font-weight:bold;font-size:18px;font-family:Arial,Helvetica,sans-serif;float:left;margin-left:5px;display:inline-block}
.chart .top_chart .t_c_name{font-weight:bold}
.chart .top_chart .hot{background-position:0 -57px}
.chart .top_chart .t_c_info{overflow: hidden;float:left;margin-left:10px}
.chart .top_chart .t_c_info .tc_i_n{font-weight:bold;font-size:12px;margin-left:35px;}
.chart .top_chart .t_c_info .tc_i_v{font-weight:normal;font-size:11px;color:#888}
.chart .tabs .tabs_content .top_chart ul li{width:100%;min-height:38px;display:inline-block;padding:5px 0 0;border-bottom:1px solid #f1f1f1;overflow:hidden;clear:both}
.chart .tabs .tabs_content .top_chart ul li:hover{background:#f5f5f5}
/* Tab select */.hide{position:absolute;top:-9999px;left:-9999px}
#tabselect .list-wrap{}

/* feautured */#featured{width:665px;position:relative;height:270px;margin-bottom:10px;overflow:hidden;background:#fff}
#featured ul.ui-tabs-nav{position:absolute;top:0;list-style:none;padding:0;margin:0;width:165px;height:270px;right:0}
#featured ul.ui-tabs-nav li{padding:0}
#featured ul.ui-tabs-nav li img{float:left;margin:0 0 1px 0;padding:0}
#featured li.ui-tabs-nav-item a{display:block;height:89px}
#featured li.ui-tabs-selected,#featured li.ui-tabs-active{}
#featured ul.ui-tabs-nav li.ui-tabs-selected a,#featured ul.ui-tabs-nav li.ui-tabs-active a{}
#featured .ui-tabs-panel{width:500px;height:269px;background:#000;position:relative}
#featured .ui-tabs-panel .play_center{width:63px;height:63px;background:url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png) -131px -51px no-repeat;position:absolute;left:221px;top:103px;z-index:5}
#featured .ui-tabs-panel .play_center:hover{background:url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png) -131px -114px no-repeat}
#featured .panel_shadow{width:44px;height:269px;background:url(http://3.bp.blogspot.com/-CCjrPpr2Yzw/U48JExmiPbI/AAAAAAAAQsw/B3yQE8Tl_Tw/s1600/slide_shadow2.png) right repeat-y;top:0;right:165px;position:absolute;z-index:1}
#featured .ui-tabs-panel img{width:500px;height:269px}
#featured .ui-tabs-panel .info{position:absolute;bottom:0;left:0;width:100%;padding-bottom:10px;background:url(http://4.bp.blogspot.com/-OHFU2EH5bz4/U48JJNJ2MAI/AAAAAAAAQs4/e2bi-3Lttuo/s1600/transparent-bg.png)}
#featured .ui-tabs-panel .info a.hideshow{position:absolute;font-size:11px;color:#f0f0f0;right:10px;top:-20px;line-height:20px;margin:0;outline:none;background:#333}
#featured .info h2{font-size:1.2em;color:#fff;padding:5px 10px;margin:0;font-weight:bold;overflow:hidden}
#featured .info p{margin:0 10px;font-size:11px;line-height:15px;color:#fff}
#featured .info a{text-decoration:none;color:#fff}
/*#featured .ui-tabs-hide{display:none}
*//* filter */.filter{height:48px;border-top:1px solid #212B4E;font-size:11px;width:980px;background:url(http://1.bp.blogspot.com/-hIAuR19bOzA/U48Fu7VG6OI/AAAAAAAAQqQ/vz1n60t6GWc/s1600/filter.png) top repeat-x;margin:0 auto;border-bottom:1px solid #000;clear:both}
.filter .content{padding:7px 10px 5px}
.filter_name{cursor:default;color:#fff;width:102px;padding-left:50px;background:url(http://1.bp.blogspot.com/-xI9PxsCxoys/U48FvX623ZI/AAAAAAAAQqU/lFprGTMTm8k/s1600/filter_film.png) 0 0;margin:-7px 0 -5px -10px;height:48px;line-height:48px;display:inline-block;font-weight:bold;float:left}
.filter_submit{text-align:center;width:70px;text-align:center;height:30px;line-height:28px;border:1px solid #1A3C97;display:inline-block;font-weight:bold;font-size:11px;color:#000;float:left;background:#132C6F;border-radius:5px;color:#fff;float:left;margin-left:10px}
.filter_link{float:left;width:auto !important;text-align:center;line-height:28px;padding:0 15px}
.filter_link,.sbHolder{background:#040818;border:1px solid #212B4E;color:#fff !important;border-radius:5px;font-size:11px;font-weight:bold;height:30px;position:relative;width:120px;float:left;margin-left:10px;z-index:2}
.sbSelector{color:#fff;font-weight:bold}
.sbSelector{display:block;height:30px;left:0;line-height:28px;outline:none;overflow:hidden;position:absolute;text-indent:10px;top:0;width:120px}
.sbToggle{background:url(#) 0 -116px no-repeat;display:block;height:24px;outline:none;position:absolute;right:0;top:0;width:22px}
.sbToggleOpen{background:url(#) 0 -16px no-repeat}
.sbOptions{background-color:#fff;border:solid 1px #aaa;box-shadow:0 0 5px rgba(0,0,0,0.3);border-radius:5px;margin-top:5px !important;list-style:none;left:-1px;margin:0;padding:0;position:absolute;top:30px;width:120px;overflow:auto;padding-bottom:10px !important}
.sbOptions li{padding:0 7px}
.sbOptions a{border-bottom:dotted 1px #515151;display:block;outline:none;padding:7px 0 7px 3px}
/* crum */.title_crum{height:36px;line-height:34px;color:#fff;font-size:14px;float:left;text-transform:uppercase;font-weight:bold;font-family:Arial,Helvetica,sans-serif}
.title_crum span{float:left}
.title_crum .t_c_s{font-size:11px;font-style:italic;margin-left:10px;text-transform:none}
