.slide{height:272px;width:980px;overflow:hidden;position:relative;z-index:2;margin:0 auto;}
.mycarousel,.slide .mycarousel ul{width:980px;height:272px;display:block;padding:0;}
.slide .mycarousel ul li{float:left;width:196px;height:272px;position:relative;}
.slide .mycarousel ul li .sl_thumb{width:196px;height:272px;}
.slide .mycarousel ul li .slide_shadow{width:48px;height:272px;background:url(http://1.bp.blogspot.com/-e93lU-F2IX4/U48IqmEXbAI/AAAAAAAAQso/7E-ZCz4BiDU/s1600/slide_shadow.png) right repeat-y;top:0;right:0;position:absolute;}
.slide .mycarousel ul li .slide_desc{position:absolute;bottom:0;left:0;}
.slide .mycarousel ul li .slide_desc .sld_content{min-height:32px;width:196px;position:relative;background:url(http://1.bp.blogspot.com/-KZ5xBupEd6M/U48J9PPk6II/AAAAAAAAQtM/nvgXXQUxgl0/s1600/dot.png) repeat;display:inline-block;text-align:center;padding-top:6px;padding-bottom:6px;}
.slide .mycarousel ul li .slide_desc h1{font-size:11px;color:#fff;line-height:1.4em;}
.slide .mycarousel ul li .slide_desc .name_sl1{font-size:11px;color:#fff;line-height:1.4em;font-weight:bold;}
.slide .mycarousel ul li .sl_tag{background:#ff0;height:16px;padding-left:8px;padding-right:8px;font-weight:bold;text-transform:uppercase;line-height:16px;border-radius:16px;display:inline-block;font-family:Arial;font-size:11px;position:absolute;left:5px;top:5px;}
.slide .mycarousel ul li .slide_desc h2,.slide .mycarousel ul li .slide_desc .name_sl2{font-weight:normal;font-size:11px;color:#fff;line-height:1.4em;}
.slide .next{position:absolute;top:95px;right:0;width:38px;height:110px;cursor:pointer;background:transparent url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png) no-repeat -50px -50px;z-index:5;}
.slide .prev{position:absolute;top:95px;left:0;width:38px;height:110px;cursor:pointer;background:transparent url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png) no-repeat -90px -50px;z-index:5;}
.next:hover{background-position:-50px -160px;}
.prev:hover{background-position:-90px -160px;}
