#list_tap ul li.ep a.a_tap,#list_tap ul li.ep a.a_tap:hover,#list_tap ul li.ep a.active{background:none repeat scroll 0 0 #171F35;color:#F9F9F9;display:inline-block;min-width:30px;float:left;-webkit-border-radius:2px;-moz-border-radius:2px;border-radius:2px;text-align:center;font-size:11px;margin:2px 0;padding:2px 3px}
#list_tap ul li.ep a.active{background:none repeat scroll 0 0 #80B500;color:#fff}
.more{font-weight:bold;margin-bottom:18px;margin-right:22px;text-align:right;}
.more a{color:#232323;border-bottom:1px dashed #ccc;padding:2px;}
.pagination{margin-top:10px;float:right;}
.pagination a,.pagination span{display:block;float:left;margin-left:5px;position:relative;background:#fff;border:1px solid #CCC;box-shadow:0 1px 1px rgba(255,255,255,0.1) inset;padding:2px 7px;}
.pagination a:hover,.pagination a.click{background:none repeat scroll 0 0 #4D90FE;color:#fff;}
.PopularPosts ul li:first-child:after,.PopularPosts ul li:first-child + li:after,.PopularPosts ul li:first-child + li + li:after,.PopularPosts ul li:first-child + li + li + li:after,.PopularPosts ul li:first-child + li + li + li + li:after,.PopularPosts ul li:first-child + li + li + li + li + li:after,.PopularPosts ul li:first-child + li + li + li + li + li + li:after,.PopularPosts ul li:first-child + li + li + li + li + li + li + li:after,.PopularPosts ul li:first-child + li + li + li + li + li + li + li + li:after,.PopularPosts ul li:first-child + li + li + li + li + li + li + li + li + li:after{position:absolute;top:4px;left:5px;text-align:center;background:url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png) 0 -86px;width:34px;height:26px;padding-top:4px;overflow:hidden;display:inline-block;font-size:18px;font-weight:bold;font-family:Arial,Helvetica,sans-serif;line-height:20px;}
.PopularPosts ul li:first-child:after,.PopularPosts ul li:first-child + li:after,.PopularPosts ul li:first-child + li + li:after{background:url(http://3.bp.blogspot.com/-XRwFHdgWBiQ/U48F0cdnlNI/AAAAAAAAQsE/H8TBK-P-6JM/s1600/sprites.png) 0 -57px no-repeat!important;}
.PopularPosts ul li:first-child + li + li + li + li + li + li + li + li + li:after{content:"10";}
.PopularPosts ul li:first-child + li + li + li + li + li + li + li + li:after{content:"9";}
.PopularPosts ul li:first-child + li + li + li + li + li + li + li:after{content:"8";}
.PopularPosts ul li:first-child + li + li + li + li + li + li:after{content:"7";}
.PopularPosts ul li:first-child + li + li + li + li + li:after{content:"6";}
.PopularPosts ul li:first-child + li + li + li + li:after{content:"5";}
.PopularPosts ul li:first-child + li + li + li:after{content:"4";}
.PopularPosts ul li:first-child + li + li:after{content:"3";}
.PopularPosts ul li:first-child + li:after{content:"2";}
.PopularPosts ul li:first-child:after{content:"1";}
.PopularPosts ul{list-style-type:none;margin:0;padding:0;}
#ajaxloader{position:fixed!important;top:0;right:0;z-index:9999999;width:100%;height:30px;line-height:30px;display:none;background: none repeat scroll 0% 0% #040818;color:#fff;text-align:center;font-size:14px;font-weight:bold;text-transform:uppercase;opacity:0.8;}
.slide .mycarousel ul li .slide_desc .sl_tag_target,.PopularPosts ul li{position:relative;}

