	page > numpage && page < numpage + 1 && 0 < lastnum ? (numposts = lastnum, start = totalPosts - lastnum + 1, document.write(
		'<script src="/feeds/posts/default' + textlabel + "?start-index=" + start + "&max-results=" + numposts +
		'&orderby=published&alt=json-in-script&callback=phimnew"><\/script>')) : page > numpage || page > numpage - 1 && 0 == lastnum ? document.write("") : document.write(
		rcpage[page])
};
