n+"</a>":'<a href="/'+textpage+"?v="+view+"&page="+n+'">'+n+"</a>",document.write(navpage);5<parseInt(pagelist)?document.write('<a href="/'+textpage+"?v="+view+"&page="+parseInt(pagelist)+'">\u00bb\u00bb</a></div>'):document.write("</div>")}else if(6<=pagelist&&3<page&&page<parseInt(pagelist)-2){var f=page-3,first=page-2,last=first+5;document.write('<div class="clear"></div><div class="pagination"><span>Page '+page+"/ "+parseInt(pagelist)+'</span><a href="/'+textpage+"?v="+view+'&page=1">\u00ab\u00ab</a>');
for(n=first;n<last;n++)navpage=n==npage?'<a class="click">'+n+"</a>":'<a href="/'+textpage+"?v="+view+"&page="+n+'">'+n+"</a>",document.write(navpage);document.write('<a href="/'+textpage+"?v="+view+"&page="+parseInt(pagelist)+'">\u00bb\u00bb</a></div>')}else if(6<=pagelist&&3<page&&page>parseInt(pagelist)-3){f=parseInt(pagelist)-5;first=parseInt(pagelist)-4;last=parseInt(pagelist)+1;document.write('<div class="clear"></div><div class="pagination"><span>Page '+page+"/ "+parseInt(pagelist)+'</span><a href="/'+
textpage+"?v="+view+'&page=1">\u00ab\u00ab</a>');for(n=first;n<last;n++)navpage=n==npage?'<a class="click">'+n+"</a>":'<a href="/'+textpage+"?v="+view+"&page="+n+'">'+n+"</a>",document.write(navpage);document.write("</div>")}};
